import {googleState,clearGoogle} from './google-route.mjs';
export function mountGooglePanel(root,{s,T,esc,time,N,onSource,onRefresh,onKey}){let section=document.createElement('div');section.className='card google-weather';root.append(section);let enabled=s.weatherSource!=='openmeteo',count=s.sites.length*8;section.innerHTML=`<h2>Google Weather API</h2><p>${T('Google综合预报（WeatherNext 3技术支持），不能指定底层模型版本。','Prévisions intégrées Google, technologie WeatherNext 3, sans sélection de version.','Google integrated forecasts (WeatherNext 3 technology); no underlying model version selection.')}</p><label><input id="googleEnabled" type="checkbox" ${enabled?'checked':''}> ${T('启用Google全线查询与施工判定','Activer Google pour toute la route et le tableau','Enable Google route-wide forecasts and construction assessment')}</label><label>${T('施工判定数据源','Source du tableau','Construction assessment source')}</label><select id="weatherSource">${[['openmeteo','Open-Meteo'],['google','Google'],['combined',T('综合：两者取更严格等级','Combiné : niveau le plus strict','Combined: more restrictive risk')]].map(([k,v])=>`<option value="${k}" ${s.weatherSource===k?'selected':''}>${v}</option>`).join('')}</select>${enabled?`<label for="googleKey">${T('Google API密钥（仅会话内；重新打开需输入）','Clé Google (session ; ressaisir après fermeture)','Google API key (session only; re-enter after restart)')}</label><input type="password" id="googleKey" autocomplete="off" value="${esc(googleState.key)}"><p>${T('每次全线刷新最多','Maximum par actualisation','Maximum per full-route refresh')} <strong>${count}</strong> ${T('次请求；每天两次约','requêtes ; deux fois par jour : environ','requests; twice daily is about')} <strong>${count*60}</strong> ${T('次/月（30天）。按Google账单计费。','requêtes/mois (30 jours). Selon la facturation Google.','requests/month (30 days). Google billing applies.')}</p><p>${T('按项目时区06:00和14:00刷新，仅应用运行且密钥已输入时；重新打开后补刷。','À 06 h et 14 h du fuseau projet, application ouverte avec clé ; rattrapage à la réouverture.','Refresh at 06:00 and 14:00 in the project time zone while the app runs with a key; catch up after reopening.')}</p><button id="googleFetch" ${googleState.busy?'disabled':''}>${T('立即刷新全线','Actualiser toute la route','Refresh entire route')}</button>${googleState.busy?`<button id="googleCancel">${T('取消Google后续请求','Annuler les requêtes suivantes','Cancel remaining Google requests')}</button>`:''}<p>${googleState.done}/${googleState.total} · ${googleState.fetched?time(googleState.fetched/1000):'—'}</p><pre>${esc(googleState.error)}</pre><p class="note">${T('Google原始数据仅在会话内；不足24小时的前期雨量不补零，土方/沥青可能显示待核实。雷暴天气代码触发红色；雷暴概率≥30%为黄色核实提示。','Google en mémoire uniquement ; pluie antérieure manquante non remplacée par zéro. Orage annoncé : rouge ; probabilité ≥30 % : alerte jaune.','Google data stays in session memory. Missing preceding 24-hour rain is not zero-filled; earthworks/asphalt may remain unverified. Thunderstorm condition: red; thunderstorm probability ≥30%: yellow verification alert.')}</p>`:''}`;
 section.querySelector('#googleEnabled').onchange=e=>onSource(e.target.checked?'google':'openmeteo');section.querySelector('#weatherSource').onchange=e=>onSource(e.target.value);
 if(enabled){section.querySelector('#googleKey').oninput=e=>{googleState.key=e.target.value;clearGoogle();onKey?.()};section.querySelector('#googleFetch').onclick=()=>onRefresh().catch(e=>{googleState.error=e.message});section.querySelector('#googleCancel')?.addEventListener('click',()=>googleState.controller?.abort())}
}
